import{_ as a,c as e,a0 as r,o}from"./chunks/framework.p2VkXzrt.js";const m=JSON.parse('{"title":"紫菜为什么煮后呈绿色","description":"","frontmatter":{},"headers":[],"relativePath":"自然科学/营养学/紫菜煮后变绿.md","filePath":"自然科学/营养学/紫菜煮后变绿.md","lastUpdated":1733761377000}'),s={name:"自然科学/营养学/紫菜煮后变绿.md"};function n(p,t,_,c,d,l){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="紫菜为什么煮后呈绿色" tabindex="-1">紫菜为什么煮后呈绿色 <a class="header-anchor" href="#紫菜为什么煮后呈绿色" aria-label="Permalink to &quot;紫菜为什么煮后呈绿色&quot;">​</a></h1><p><a href="https://m.sohu.com/a/252291871_414079?_trans_=010004_pcwzy" target="_blank" rel="noreferrer">https://m.sohu.com/a/252291871_414079?_trans_=010004_pcwzy</a></p><p>紫菜之所以是紫色的，是因为紫菜中含有一种叫“藻红素”的特殊色素蛋白。<strong>藻红素可以溶解到水里。</strong> 并且，这种色素蛋白并不稳定，<strong>特别是遇热容易分解</strong>。</p><p>所以，在煮汤时，失去藻红素的紫菜就褪去了它们原有的紫色，变成了绿色。这是因为，除了藻红素，<strong>紫菜中还含有叶绿素、胡萝卜素和叶黄素等色素。</strong> 在它们中间，叶绿素的含量最高。它取代了藻红素的位置，从而将叶片“变成”绿色。它与蔬菜中的叶绿素是一样的，没有毒性。</p><p>那些长期储存的紫菜，也因为藻红素逐渐降解而变成绿色，也是正常现象，可以放心吃。</p>',5)]))}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
